import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { WritingInspectionPage } from './writing-inspection.page';

const routes: Routes = [
  {
    path: '',
    component: WritingInspectionPage
  },
  {
    path: 'my-inspection',
    loadChildren: () => import('./my-inspection/my-inspection.module').then( m => m.MyInspectionPageModule)
  },
  {
    path: 'my-inspection-dashboard',
    loadChildren: () => import('./my-inspection-dashboard/my-inspection-dashboard.module').then( m => m.MyInspectionDashboardPageModule)
  },
  {
    path: 'my-inspection-question',
    loadChildren: () => import('./my-inspection-question/my-inspection-question.module').then( m => m.MyInspectionQuestionPageModule)
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class WritingInspectionPageRoutingModule {}
